-- Desk attribution and ledger fields (G-DESK-01, G-ORD-01, G-RISK-01, G-LED-01).
-- Additive only: new enums, nullable columns, indexes and CHECK constraints
-- that every existing row satisfies. Generated by `prisma migrate diff` and
-- edited only where Prisma cannot express the intent (marked below).

-- CreateEnum
CREATE TYPE "MandateMetric" AS ENUM ('GROSS_LEVERAGE', 'NET_EXPOSURE_RATIO', 'SINGLE_NAME_CONCENTRATION', 'MAX_SECTOR_CONCENTRATION', 'DAILY_LOSS', 'DRAWDOWN', 'VAR_95', 'VAR_99', 'EXPECTED_SHORTFALL_95', 'MARGIN_UTILIZATION', 'OPEN_POSITIONS');

-- CreateEnum
CREATE TYPE "MandateAction" AS ENUM ('BLOCK', 'ESCALATE', 'HALT', 'DERISK');

-- CreateEnum
CREATE TYPE "MandateRuleGroup" AS ENUM ('EXPOSURE', 'LOSS', 'LIQUIDITY');

-- CreateEnum
CREATE TYPE "DeskType" AS ENUM ('EVENT', 'THEMATIC', 'SYSTEMATIC');

-- Hand-edited: Prisma does not model sequences. The ledger sequence must exist
-- before the column default names it, and the default is set AFTER the column
-- is added so existing rows keep a NULL ledgerSeq: adding the column with a
-- volatile default would number every historical row in physical order, an
-- order its timestamps do not establish.
CREATE SEQUENCE "audit_logs_ledger_seq" AS BIGINT START WITH 1 INCREMENT BY 1 NO CYCLE;

-- AlterTable
ALTER TABLE "audit_logs" ADD COLUMN     "fundId" UUID,
ADD COLUMN     "ledgerSeq" BIGINT;

ALTER TABLE "audit_logs" ALTER COLUMN "ledgerSeq" SET DEFAULT nextval('audit_logs_ledger_seq'::regclass);

ALTER SEQUENCE "audit_logs_ledger_seq" OWNED BY "audit_logs"."ledgerSeq";

-- AlterTable
ALTER TABLE "mandate_rules" ADD COLUMN     "action" "MandateAction",
ADD COLUMN     "group" "MandateRuleGroup",
ADD COLUMN     "metricKey" "MandateMetric",
ADD COLUMN     "ruleCode" VARCHAR(32);

-- Hand-edited: Prisma does not model CHECK constraints. A rule naming a
-- measured quantity is a limit gauge, and a gauge needs its cap, its action,
-- its group and the code it is cited by; a code, when present, is not blank.
-- Existing rows have no metricKey and no ruleCode, so both hold for them.
ALTER TABLE "mandate_rules" ADD CONSTRAINT "mandate_rules_metric_complete_check"
  CHECK ("metricKey" IS NULL OR ("threshold" IS NOT NULL AND "action" IS NOT NULL AND "group" IS NOT NULL AND "ruleCode" IS NOT NULL));

ALTER TABLE "mandate_rules" ADD CONSTRAINT "mandate_rules_rule_code_not_blank_check"
  CHECK ("ruleCode" IS NULL OR length(btrim("ruleCode")) > 0);

-- AlterTable
ALTER TABLE "strategies" ADD COLUMN     "desk" "DeskType";

